 const c=figma.createComponent();c.name='Tab Bar/'+cur;c.resize(414,84);c.fills=[S('#FFFFFF')];c.strokes=[S(BORDER)];c.strokeWeight=1;c.strokeAlign='INSIDE';
 c.layoutMode='HORIZONTAL';c.paddingLeft=30;c.paddingRight=30;c.counterAxisAlignItems='CENTER';c.primaryAxisAlignItems='SPACE_BETWEEN';c.primaryAxisSizingMode='FIXED';c.counterAxisSizingMode='FIXED';
 const tabs=[['Home',IC.home],['Visits',IC.visits],['Plus',IC.plus],['Chat',IC.chat],['Profile',IC.profile]];
 for(const [nm,iid] of tabs){
  if(nm==='Plus'){const b=F('Tab Plus',52,52);b.cornerRadius=26;b.fills=[S(GREEN)];b.layoutMode='HORIZONTAL';b.primaryAxisAlignItems='CENTER';b.counterAxisAlignItems='CENTER';b.primaryAxisSizingMode='FIXED';b.counterAxisSizingMode='FIXED';b.appendChild(ic(iid,24,'#FFFFFF','Icon'));c.appendChild(b);continue;}
  const col=F('Tab '+nm,44,44);col.layoutMode='VERTICAL';col.counterAxisAlignItems='CENTER';col.itemSpacing=4;col.fills=[];
  const active=nm===cur;const colr=active?GREEN:'#B4BCB8';
  col.appendChild(ic(iid,24,colr,'Icon'));
  col.appendChild(T(nm,10,IM,colr,'Label'));
  c.appendChild(col);
 }
 comp(c);return c;
}
