 try{btn.reactions=[{trigger:{type:'ON_CLICK'},action:{type:t}}];results[t]='OK';}
 catch(e){const m=e.message;
  if(m.includes('expected "CONDITIONAL"')&&m.includes("'"+t+"'")) results[t]='rejected-type';
  else if(m.includes('received \''+t+'\'')) results[t]='unknown-type';
  else {
   // find which required props were demanded
   const reqs=[...m.matchAll(/Required value missing at \[0\]\.action\.(\w+)/g)].map(x=>x[1]);
   const en=[...m.matchAll(/Invalid enum value\. Expected (.*?), received/g)].map(x=>x[1]);
   results[t]=JSON.stringify({reqs:[...new Set(reqs)],en:en[0]||null});
  }}
}
return JSON.stringify(results);

