for(const ch of page.children){if(ch.type==='FRAME'&&/^\d\d_/.test(ch.name))frames[ch.name]=ch.id;}
const mk=(dst)=>[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:frames[dst],navigation:'NAVIGATE',transition:{type:'DISSOLVE',easing:{type:'EASE_IN_AND_OUT'},duration:0.3}}]}];
const v08=page.findOne(n=>n.name==='08_Home');
const sa=v08.findOne(n=>n.name==='Popular Doctors Header').findOne(n=>n.name==='See All');
sa.name='lnk:10_Doctors';sa.reactions=mk('10_Doctors');
const v17=page.findOne(n=>n.name==='17_Video_Call');
for(const c of v17.findOne(n=>n.name==='Call Controls').children){
 c.fills=[c.name==='lnk:15_Chat'?{type:'SOLID',color:{r:0.949,g:0.408,b:0.361}}:{type:'SOLID',color:{r:1,g:1,b:1},opacity:0.25}];
}
return 'See All + 17 fills done';

const page=figma.getNodeById('3:2');
await figma.setCurrentPageAsync(page);
const names=['01_Onboarding','02_Choose_Role','03_About_You','04_Sign_In','05_Sign_Up','06_Sign_Up_Error','07_Verify_Code','08_Home','09_Visit','10_Doctors','11_Doctor_Profile','12_Booking_Confirmed','13_Payment','14_Chats','15_Chat','16_Prescriptions','17_Video_Call'];
const rep=[];
for(const nm of names){
 const f=page.findOne(n=>n.name===nm);
 if(!f){rep.push(nm+': MISSING');continue;}
 const txt=f.findAll(n=>n.type==='TEXT').map(t=>t.characters).join(' ');
 const icons=f.findAll(n=>n.type==='INSTANCE').length;
 const lnks=f.findAll(n=>n.name&&n.name.includes('lnk:')).length;
 rep.push(nm+' ['+Math.round(f.width)+'x'+Math.round(f.height)+'] inst='+icons+' lnk='+lnks+' | '+txt.slice(0,150));
}
const comps=page.children.filter(n=>n.type==='COMPONENT').map(n=>n.name);
return rep.join('\n')+'\n\nCOMPONENTS: '+comps.join(', ');

